<?php	/**	 * Created by PhpStorm.	 * User: MrHa	 * Date: 1/11/2015	 * Time: 11:41 PM	 */	$data = wp_parse_args( $attr, array(		'posts_per_page'  => 8,		'category'        => '',		'show_filter'     => 'yes',		'orderby'         => 'none',		'order'           => 'desc',		'enable_loadmore' => FALSE	) );	extract( $data );	$args = array(		'post_type'      => 'portfolio',		'posts_per_page' => $posts_per_page,		'order'          => $order,		'orderby'        => $orderby,	);	$is_all = btp_is_all_cat( $category );	if ( ! $is_all ) {		$args['tax_query'][] = array(			'taxonomy' => 'portfolio_cat',			'terms'    => explode( ',', $category )		);	}	$category_array = explode( ',', $category );	$filter_html = '';	if ( $show_filter == 'yes' ) {		$filter_html = '<div id="portfolio-filter" class="text-center"><ul class="portfolio-filter-list">';		$term_arg = array();		if ( ! $is_all ) {			$term_arg = $category_array;		}		$filter_html .= '<li><a  href="#" class="active" data-cat="*">' . __( 'ALL', HATT_TEXTDOMAIN ) . '</a></li>';		$terms = get_terms( 'portfolio_cat', $term_arg );		if ( ! empty( $terms ) && ! is_wp_error( $terms ) ) {			foreach ( $terms as $val ) {				$filter_html .= '<li><a href="#" data-cat="' . $val->slug . '">' . $val->name . '</a></li>';			}		}		$filter_html .= "</ul></div>";	}	$html = '<div id="portfolio-items" class="portfolio-items">';	$category_data = new WP_Query( $args );	if ( $category_data->have_posts() ) {		while ( $category_data->have_posts() ) {			$category_data->the_post();			$html .= Hatt()->load_template( 'portfolio/grid-loop', FALSE, $data );		}	}	$html .= '</div>';	if ( $enable_loadmore ) {		$html .= '<p class="text-center"><a class="btn btn-default btn-lg" id="load_more_portfolio" href="#" onclick="return false" data-page=2 attr_post_per_page="' . $posts_per_page . '" attr_category="' . $category . '" attr_orderby="' . $orderby . '" attr_order="' . $order . '">' . __( 'Load More', HATT_TEXTDOMAIN ) . '</a></p>';	}	wp_reset_postdata();?>	<div id="portfolio-wrap">		<div id="portfolio-page">			<div id="portfolio-content">				<div class="container">					<div id="protfolio-control">						<div class="row">							<div class="col-md-4 col-sm-4 col-xs-4">								<a href="#" id="prev-project"								   title="<?php _e( 'Previous Project', HATT_TEXTDOMAIN ) ?>"><i										class="fa fa-arrow-left"></i></a>							</div>							<div class="col-md-4 col-sm-4 col-xs-4 text-center">								<a href="#" id="close-project"								   title="<?php _e( 'Close Project', HATT_TEXTDOMAIN ) ?>"><i										class="fa fa-times"></i></a>							</div>							<div class="col-md-4 col-sm-4 col-xs-4 text-right">								<a href="#" id="next-project" title="<?php _e( 'Next Project', HATT_TEXTDOMAIN ) ?>"><i										class="fa fa-arrow-right"></i></a>							</div>						</div>					</div>					<!-- End #protfolio-control -->					<!-- Ajax will load into here -->					<div id="portfolio-ajax">					</div>					<!-- End #portfolio-ajax -->					<!-- End Ajax -->				</div>				<!-- End .container -->			</div>			<!-- End #portfolio-content -->		</div>		<!-- End #portfolio-page -->	</div>	<!-- End #portfolio-wrap --><?php	echo $filter_html . $html;